--Round Robin 

CREATE TABLE round_table(
   id INT,
   name VARCHAR(20)
)
WITH(
    DISTRIBUTION = ROUND_ROBIN
);

INSERT INTO round_table(id,name)
VALUES (1,'naiya');

SELECT * FROM round_table


--REPLICATE 
CREATE SCHEMA gold;

CREATE TABLE gold.dim_product(
   prod_key INT,
   prod_name VARCHAR(20)
)
WITH(
    DISTRIBUTION = REPLICATE
);


--HASH

CREATE TABLE gold.dim_fact(
   prod_key INT,
   revenue INT,
   cost INT
)
WITH(
    DISTRIBUTION = HASH(prod_key)
);
